import {
	Mesh,
	PlaneGeometry,
	Object3D,
	Color,
	DoubleSide,
	Vector2,
} from 'three/webgpu';
import {
	MeshBasicNodeMaterial,
	colorNode,
	uv,
	texture,
	add,
	mul,
	step,
	float,
	vec2,
} from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import { fontAtlasRegion } from '@/text';

export default function createNode(config, ctx) {
	// Root container
	const root = new Object3D();

	// Apply placement
	if (config.position) root.position.set(...config.position);
	if (config.rotation) root.rotation.set(...config.rotation);
	if (config.scale) root.scale.set(...config.scale);
	else root.scale.set(1, 1, 1);

	// --------- Background Image Plane ----------
	const imgUrl = config.assets?.imageUrl;
	const bgTexture = imgUrl ? ctx.textureLoader.load(imgUrl) : null;
	if (bgTexture) bgTexture.flipY = false;

	const bgGeom = new PlaneGeometry(1, 1);
	const bgMat = new MeshBasicNodeMaterial({
		side: DoubleSide,
		transparent: true,
	});
	if (bgTexture) {
		bgMat.colorNode = colorNode(0xffffff);
		bgMat.mapNode = texture(bgTexture);
	}
	const bgMesh = new Mesh(bgGeom, bgMat);
	root.add(bgMesh);

	// --------- Text Plane (MSDF) ----------
	const rawText = (config.textContent && config.textContent[0] && config.textContent[0].text) || 'Collection';
	const atlas = ctx.fontAtlas; // MSDF atlas texture
	const atlasInfo = ctx.fontAtlasInfo || {
		atlasIndex: 0,
		rect: { x: 0, y: 0, w: 512, h: 320 }, // fallback from specification
	};

	// Compute UV transform to sample the required region
	const texSize = new Vector2(atlas.image?.width || 1, atlas.image?.height || 1);
	const region = atlasInfo.rect;
	const scaleUV = vec2(
		float(region.w / texSize.x),
		float(region.h / texSize.y)
	);
	const offsetUV = vec2(
		float(region.x / texSize.x),
		float(region.y / texSize.y)
	);
	const transformedUV = add(mul(uv(), scaleUV), offsetUV);

	const atlasTexNode = texture(atlas, transformedUV);
	// Simple threshold for alpha (assumes red channel stores distance)
	const alphaNode = step(float(0.5), atlasTexNode.r);

	const textMat = new MeshBasicNodeMaterial({
		side: DoubleSide,
		transparent: true,
		depthWrite: false,
	});
	textMat.colorNode = colorNode(new Color('#16161d')); // ink color
	textMat.alphaNode = alphaNode;
	textMat.mapNode = atlasTexNode; // keep map for potential future use

	const textGeom = new PlaneGeometry(1, 1);
	const textMesh = new Mesh(textGeom, textMat);
	// Slightly in front of the background to avoid z‑fighting
	textMesh.position.set(0, 0, 0.01);
	root.add(textMesh);

	// --------- Apply Cinematic Primitives (none in this spec) ----------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const primitive of config.cinematicPrimitives) {
			const fn = ctx.primitives[primitive.name];
			if (typeof fn === 'function') {
				fn(root, primitive.params);
			}
		}
	}

	// --------- Event Handlers Placeholder ----------
	root.userData.handlers = {};

	// --------- Cleanup ----------
	const timelines = []; // collect any GSAP timelines if created later
	root.userData.cleanup = () => {
		// Dispose geometry & materials
		bgGeom.dispose();
		bgMat.dispose();
		textGeom.dispose();
		textMat.dispose();

		// Dispose textures
		if (bgTexture) bgTexture.dispose();
		if (atlas) atlas.dispose();

		// Kill GSAP timelines
		for (const tl of timelines) {
			if (tl && typeof tl.kill === 'function') tl.kill();
		}
	};

	return root;
}
